## Summary
- count `DIV` elements as newline characters when computing the caret so the cursor advances after pressing Enter while still preserving any trailing line breaks in the hidden input
- retain `<div>`-based line breaks and store the same text in the hidden input
- guard against recursive input events and delay caret restoration so the cursor remains at the expected position after formatting

## Testing
- `node --check dynamic-formatting.js`
- `node - <<'NODE'
const fs = require('fs');
const {JSDOM} = require('jsdom');
const html = `<!DOCTYPE html><div id="detailsEditable" contenteditable="true"></div><input type="hidden" id="detailsInput">`;
const dom = new JSDOM(html, { runScripts: 'dangerously' });
Object.defineProperty(dom.window.HTMLElement.prototype, 'innerText', {
  configurable: true,
  get() {
    let text = '';
    function traverse(node, root) {
      if (node.nodeType === dom.window.Node.TEXT_NODE) {
        text += node.textContent;
      } else {
        for (const child of node.childNodes) traverse(child, root);
        if (node.nodeName === 'BR') text += '\n';
        else if (node.nodeName === 'DIV' && node !== root && (!node.lastChild || node.lastChild.nodeName !== 'BR')) text += '\n';
      }
    }
    traverse(this, this);
    return text;
  },
  set(v){ this.textContent = v; }
});
dom.window.dynamicFormattingEnabled = true;
const script = fs.readFileSync('dynamic-formatting.js', 'utf-8');
dom.window.eval(script);
const event = dom.window.document.createEvent('Event');
event.initEvent('DOMContentLoaded', true, true);
dom.window.document.dispatchEvent(event);
const el = dom.window.document.getElementById('detailsEditable');
const hidden = dom.window.document.getElementById('detailsInput');

function caretPos(root) {
  const sel = dom.window.getSelection();
  if (!sel || sel.rangeCount === 0) return 0;
  const range = sel.getRangeAt(0);
  let pos = 0;
  function traverse(node) {
    if (node === range.endContainer) {
      pos += range.endOffset;
      return true;
    }
    if (node.nodeType === dom.window.Node.TEXT_NODE) {
      pos += node.textContent.length;
    } else {
      for (const child of node.childNodes) {
        if (traverse(child)) return true;
      }
      if (node.nodeName === 'BR' || (node.nodeName === 'DIV' && node !== root)) {
        pos += 1;
      }
    }
    return false;
  }
  traverse(root);
  return pos;
}

// simulate typing 'foo' then pressing Enter
el.innerHTML = '<div>foo</div><div><br></div>';
const range = dom.window.document.createRange();
const secondDiv = el.childNodes[1];
range.setStart(secondDiv, 0);
range.collapse(true);
const sel = dom.window.getSelection();
sel.removeAllRanges();
sel.addRange(range);
console.log('caret before update:', caretPos(el));
el.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
setTimeout(() => {
  console.log('after enter HTML:', JSON.stringify(el.innerHTML));
  console.log('caret after enter:', caretPos(el));

  // paste multiline text
  el.innerText = 'foo\nbar';
  el.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
  setTimeout(() => {
    console.log('innerHTML:', JSON.stringify(el.innerHTML));
    console.log('hidden:', JSON.stringify(hidden.value));

    // trailing newline
    el.innerText = 'foo\n';
    el.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
    setTimeout(() => {
      console.log('innerHTML trailing:', JSON.stringify(el.innerHTML));
      console.log('hidden trailing:', JSON.stringify(hidden.value));
    }, 0);
  }, 0);
}, 0);
NODE`

